#include <stdio.h>
int main(void) {
    FILE *fp = fopen("/tmp/mcq17.bin", "wb");
    int arr[3] = {10, 20, 30};
    fwrite(arr, sizeof(int), 3, fp);
    fclose(fp);
    fp = fopen("/tmp/mcq17.bin", "rb");
    int x;
    fseek(fp, sizeof(int) * 1, SEEK_SET);
    fread(&x, sizeof(int), 1, fp);
    fclose(fp);
    printf("%d\n", x);
    return 0;
}

