#include <stdio.h>
int main(void) {
    FILE *fp = fopen("/tmp/mcq18.txt", "w");
    fprintf(fp, "Hello");
    fclose(fp);
    fp = fopen("/tmp/mcq18.txt", "r");
    int c;
    int count = 0;
    while ((c = fgetc(fp)) != EOF) {
        count++;
    }
    fclose(fp);
    printf("%d\n", count);
    return 0;
}

